import React, { useState, useEffect, useRef } from 'react';
import '../styles/Hero.css';
import { Link } from 'react-router-dom';

const Hero = () => {
  const [dropdownAbierto, setDropdownAbierto] = useState(false);
  const dropdownRef = useRef(null);

  const toggleDropdown = () => {
    setDropdownAbierto(!dropdownAbierto);
  };

  // Cierra el menú si se hace clic fuera de él
  useEffect(() => {
    const handleClickOutside = (event) => {
      if (dropdownRef.current && !dropdownRef.current.contains(event.target)) {
        setDropdownAbierto(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => {
      document.removeEventListener('mousedown', handleClickOutside);
    };
  }, [dropdownRef]);

  return (
    <section
      className="hero-section"
      style={{ background: "url('https://res.cloudinary.com/diyd6flkf/image/upload/v1760021191/hero-bg_cgs5qy.jpg') center/cover no-repeat" }}
    >
      {/* --- BARRA DE NAVEGACIÓN AÑADIDA --- */}
      <header className="hero-header">
        <nav className="hero-nav">
          <Link to="/" className="nav-logo">PHG Soluciones</Link>
          <div className="nav-links">
            <Link to="/" className="nav-link">Inicio</Link>
            <div className="dropdown" ref={dropdownRef}>
              <button onClick={toggleDropdown} className="nav-link dropbtn">
                Nosotros
              </button>
              {dropdownAbierto && (
                <div className="dropdown-content">
                  <Link to="/mision" onClick={() => setDropdownAbierto(false)}>Misión</Link>
                  <Link to="/vision" onClick={() => setDropdownAbierto(false)}>Visión</Link>
                </div>
              )}
            </div>
            <Link to="/servicios" className="nav-link">Servicios</Link>
            <Link to="/#contacto-form" className="nav-link">Contacto</Link>
          </div>
        </nav>
      </header>

      <div className="hero-overlay">
        <div className="hero-content">
          <h2 className="hero-subtitle">PHG SOLUCIONES CONTABLES</h2>
          <h1 className="hero-title">SERVICIO CONTABLE DE ALTA PRECISIÓN</h1>
          <p className="hero-desc">Impulsamos tu crecimiento con asesoría financiera estratégica y soporte cercano.</p>
          <Link to="/#contacto-form" className="hero-btn">
            ¡SOLICITA UNA ASESORÍA AHORA!
          </Link>
        </div>
      </div>
    </section>
  );
};

export default Hero;
